#[allow(dead_code)]
mod common;
use common::{distinct, equal, ordered};
use std::ops::{Add, Neg, Sub};
use timetuck::{Decimal, HardSoftDecimalScore};
fn d(text: &str) -> Decimal {
    text.parse().unwrap()
}

#[test]
fn of() {
    assert_eq!(
        HardSoftDecimalScore::of_hard(d("-147.2")),
        HardSoftDecimalScore::new(d("-147.2"), d("0.0"))
    );
    assert_eq!(
        HardSoftDecimalScore::of_soft(d("-3.2")),
        HardSoftDecimalScore::new(d("-0.0"), d("-3.2"))
    );
}

#[test]
fn of_keeps_scale_of_non_zero_level() {
    assert_eq!(
        HardSoftDecimalScore::new(d("1.0"), d("0")).hard().scale(),
        1
    );
}

#[test]
fn parse_score() {
    assert_eq!(
        "-147.2hard/-258.3soft"
            .parse::<HardSoftDecimalScore>()
            .unwrap(),
        HardSoftDecimalScore::new(d("-147.2"), d("-258.3"))
    );
    assert_eq!(
        "-1structural/0hard/-258.3soft"
            .parse::<HardSoftDecimalScore>()
            .unwrap(),
        HardSoftDecimalScore::from_parts(-1, [d("0"), d("-258.3")])
    );
}

#[test]
fn to_short_string() {
    assert_eq!(
        HardSoftDecimalScore::new(d("0.0"), d("0.0")).to_short_string(),
        "0"
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("0.0"), d("-258.3")).to_short_string(),
        "-258.3soft"
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("-147.2"), d("0.0")).to_short_string(),
        "-147.2hard"
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("-147.2"), d("-258.3")).to_short_string(),
        "-147.2hard/-258.3soft"
    );
    assert_eq!(
        HardSoftDecimalScore::from_parts(-1, [d("-147.2"), d("-258.3")]).to_short_string(),
        "-1structural/-147.2hard/-258.3soft"
    );
}

#[test]
fn test_to_string() {
    assert_eq!(
        (HardSoftDecimalScore::new(d("0.0"), d("-258.3"))).to_string(),
        "0.0hard/-258.3soft"
    );
    assert_eq!(
        (HardSoftDecimalScore::new(d("-147.2"), d("-258.3"))).to_string(),
        "-147.2hard/-258.3soft"
    );
    assert_eq!(
        (HardSoftDecimalScore::from_parts(-1, [d("-147.2"), d("-258.3")])).to_string(),
        "-1structural/-147.2hard/-258.3soft"
    );
}

#[test]
fn parse_score_illegal_argument() {
    assert!("-147.2".parse::<HardSoftDecimalScore>().is_err());
    assert!(
        "-1structural/0hard"
            .parse::<HardSoftDecimalScore>()
            .is_err()
    );
}

#[test]
fn feasible() {
    assert!(!(HardSoftDecimalScore::new(d("-5"), d("-300"))).is_feasible());
    assert!(!(HardSoftDecimalScore::new(d("-5"), d("4000"))).is_feasible());
    assert!(!(HardSoftDecimalScore::new(d("-0.007"), d("4000"))).is_feasible());
    assert!(!(HardSoftDecimalScore::from_parts(-1, [d("0"), d("-300")])).is_feasible());
    assert!((HardSoftDecimalScore::new(d("0"), d("-300.007"))).is_feasible());
    assert!((HardSoftDecimalScore::new(d("0"), d("-300"))).is_feasible());
    assert!((HardSoftDecimalScore::new(d("2"), d("-300"))).is_feasible());
}

#[test]
fn add() {
    assert_eq!(
        HardSoftDecimalScore::new(d("20"), d("-20"))
            .add(HardSoftDecimalScore::new(d("-1"), d("-300"))),
        HardSoftDecimalScore::new(d("19"), d("-320"))
    );
}

#[test]
fn subtract() {
    assert_eq!(
        HardSoftDecimalScore::new(d("20"), d("-20"))
            .sub(HardSoftDecimalScore::new(d("-1"), d("-300"))),
        HardSoftDecimalScore::new(d("21"), d("280"))
    );
}

#[test]
fn multiply() {
    assert_eq!(
        HardSoftDecimalScore::new(d("5.0"), d("-5.0"))
            .multiply(&d("1.2"))
            .unwrap(),
        HardSoftDecimalScore::new(d("6.0"), d("-6.0"))
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("1.0"), d("-1.0"))
            .multiply(&d("1.2"))
            .unwrap(),
        HardSoftDecimalScore::new(d("1.2"), d("-1.2"))
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("4.0"), d("-4.0"))
            .multiply(&d("1.2"))
            .unwrap(),
        HardSoftDecimalScore::new(d("4.8"), d("-4.8"))
    );
}

#[test]
fn divide() {
    assert_eq!(
        HardSoftDecimalScore::new(d("25.0"), d("-25.0"))
            .divide(&d("5.0"))
            .unwrap(),
        HardSoftDecimalScore::new(d("5.0"), d("-5.0"))
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("21.0"), d("-21.0"))
            .divide(&d("5.0"))
            .unwrap(),
        HardSoftDecimalScore::new(d("4.2"), d("-4.2"))
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("24.0"), d("-24.0"))
            .divide(&d("5.0"))
            .unwrap(),
        HardSoftDecimalScore::new(d("4.8"), d("-4.8"))
    );
}

#[test]
fn power() {
    assert_eq!(
        HardSoftDecimalScore::new(d("-4.0"), d("5.0"))
            .power(2)
            .unwrap(),
        HardSoftDecimalScore::new(d("16.0"), d("25.0"))
    );
}

#[test]
fn multiply_clamps_negative_scale() {
    assert_eq!(
        HardSoftDecimalScore::new(d("1E+2"), d("5.0"))
            .multiply(&d("1.5"))
            .unwrap(),
        HardSoftDecimalScore::new(d("150"), d("7.5"))
    );
}

#[test]
fn divide_clamps_negative_scale() {
    assert_eq!(
        HardSoftDecimalScore::new(d("1E+2"), d("5.0"))
            .divide(&d("2.0"))
            .unwrap(),
        HardSoftDecimalScore::new(d("50"), d("2.5"))
    );
}

#[test]
fn power_clamps_negative_scale() {
    assert_eq!(
        HardSoftDecimalScore::new(d("1E+2"), d("5.0"))
            .power(0)
            .unwrap(),
        HardSoftDecimalScore::new(d("1"), d("1.0"))
    );
}

#[test]
fn negate() {
    assert_eq!(
        HardSoftDecimalScore::new(d("4.0"), d("-5.0")).neg(),
        HardSoftDecimalScore::new(d("-4.0"), d("5.0"))
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("-4.0"), d("5.0")).neg(),
        HardSoftDecimalScore::new(d("4.0"), d("-5.0"))
    );
}

#[test]
fn abs() {
    assert_eq!(
        HardSoftDecimalScore::new(d("4.0"), d("5.0")).abs(),
        HardSoftDecimalScore::new(d("4.0"), d("5.0"))
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("4.0"), d("-5.0")).abs(),
        HardSoftDecimalScore::new(d("4.0"), d("5.0"))
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("-4.0"), d("5.0")).abs(),
        HardSoftDecimalScore::new(d("4.0"), d("5.0"))
    );
    assert_eq!(
        HardSoftDecimalScore::new(d("-4.0"), d("-5.0")).abs(),
        HardSoftDecimalScore::new(d("4.0"), d("5.0"))
    );
}

#[test]
fn zero() {
    assert_eq!(
        HardSoftDecimalScore::ZERO,
        HardSoftDecimalScore::new(d("0"), d("0"))
    );
    assert!(HardSoftDecimalScore::new(d("0"), d("0")).is_zero());
    assert!(!HardSoftDecimalScore::new(d("0"), d("1")).is_zero());
}

#[test]
fn equals_and_hash_code() {
    equal(&[
        HardSoftDecimalScore::new(d("-10.0"), d("-200.0")),
        HardSoftDecimalScore::new(d("-10.0"), d("-200.0")),
        HardSoftDecimalScore::new(d("-10.000"), d("-200.000")),
    ]);
    equal(&[
        HardSoftDecimalScore::from_parts(-1, [d("-10.0"), d("-200.0")]),
        HardSoftDecimalScore::from_parts(-1, [d("-10.0"), d("-200.0")]),
    ]);
    distinct(&[
        HardSoftDecimalScore::new(d("-10.0"), d("-200.0")),
        HardSoftDecimalScore::new(d("-30.0"), d("-200.0")),
        HardSoftDecimalScore::new(d("-10.0"), d("-400.0")),
        HardSoftDecimalScore::from_parts(-1, [d("-10.0"), d("-200.0")]),
    ]);
}

#[test]
fn compare_to() {
    ordered(&[
        HardSoftDecimalScore::from_parts(-1, [d("-20.06"), d("-20")]),
        HardSoftDecimalScore::new(d("-20.06"), d("-20")),
        HardSoftDecimalScore::new(d("-20.007"), d("-20")),
        HardSoftDecimalScore::new(d("-20"), d("-20.06")),
        HardSoftDecimalScore::new(d("-20"), d("-20.007")),
        HardSoftDecimalScore::new(d("-20"), d("-20")),
        HardSoftDecimalScore::new(d("-1"), d("-300")),
        HardSoftDecimalScore::new(d("-1"), d("4000")),
        HardSoftDecimalScore::new(d("0"), d("-1")),
        HardSoftDecimalScore::new(d("0"), d("0")),
        HardSoftDecimalScore::new(d("0"), d("1")),
    ]);
}
